import{z as B,x as A,o as n,c as p,q as r,j as l,D as e,d as t,s as o,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"融资融券机制","description":"","frontmatter":{"title":"融资融券机制","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/margin-securities-lending.md","filePath":"quant/margin-securities-lending.md","lastUpdated":1791063341000}'),d={name:"quant/margin-securities-lending.md"};function u(m,a,D,c,h,f){const i=A("Mermaid");return n(),p("div",null,[a[2]||(a[2]=r('<h1 id="融资融券机制" tabindex="-1">融资融券机制 <a class="header-anchor" href="#融资融券机制" aria-label="Permalink to &quot;融资融券机制&quot;">​</a></h1><div class="epigraph"><p>多头杠杆借的是钱，空头杠杆借的是券；两套合约、两套可开仓名单、两套被召回的方式。回测里把空头写成负权重，等于假设券总能借到。</p><footer>—— 据 D&#39;Avolio, Journal of Financial Economics, 2002；Geczy, Musto and Reed, Journal of Financial Economics, 2002 整理</footer></div><p>上一课<a href="/quant/liquidation-gap-risk">强平与缺口风险</a>假设仓位已经存在、只是价格跳空。空头仓位能否存在，取决于融券；多头加杠杆，取决于融资。本课把保证金账户拆成<strong>借钱</strong>与<strong>借券</strong>两条腿。费率下一课专讲；本课先钉机制与回测里「可空」集合。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无约束多空因子对每一只股票写正负权重。实盘空头需要找到出借人，且该券在当时的可融名单上。D&#39;Avolio 描述了借券市场的供给如何随日变化：热门空头供给紧、容易被召回。Geczy–Musto–Reed 表明部分异象的空头侧在不可借或极贵时不可实施。缺口是形成日宇宙要再交一次集：当时可融资买入、当时可融券卖出。财务课的当时上市集合是超集；本课是可实施子集。</p><p><span class="marginnote">「融资融券」翻译成白话：融资=向券商借钱买股票（做多加杠杆）；融券=向券商借股票先卖出、日后买回来还（做空）。两条腿的名单和抵押逻辑都不同——借的钱用现金还，借的券必须用券还。</span></p><p>召回（recall）会强制回补，效果类似强平，但触发的是出借人要回证券，不一定是保证金击穿。</p><p><span class="marginnote">「召回」可以想成房东提前收房：你借的房子（券）住得好好的，房东说要收回，你就必须在限期内搬走（买回股票还券）。哪怕保证金完全正常也躲不掉——这是做空独有的被动平仓渠道。</span></p><h3 id="融券余额不是做空意愿的充分统计" tabindex="-1">融券余额不是做空意愿的充分统计 <a class="header-anchor" href="#融券余额不是做空意愿的充分统计" aria-label="Permalink to &quot;融券余额不是做空意愿的充分统计&quot;">​</a></h3><p>可观察到的空头利息是成交后的存量，受供给约束。供给枯竭时，想做空做不成，余额不一定大。用高空头利息当「拥挤」可以，用低空头利息当「可以自由做空」不行。回测应以可借标志与借券库存为准，而不是以事后空头利息倒推当时可开仓。</p><p><span class="marginnote">中国融资融券有标的名单与保证金比例，名单调整本身是事件。用今日标的回填历史，是制度版幸存者。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>开空前检查：该证券在 \\(t\\) 是否可借、要求的保证金、是否已被限定为只能平仓。开融资多头检查：是否在融资标的、折算率。召回到达时，按规则在限期内回补，成交价用当时可成交价，走上一课缺口逻辑。不要在回测结束时才丢掉「从未出现在借券库」的名字——那会留下易借的幸存者。</p><p>财务因子的空头往往是小市值、低质量、难借的券。可实施过滤会显著削弱纸面空头收益，这应被视为正确的衰减，不是要被「数据清洗」加回去的损失。</p>',14)),(n(),l(s,null,{default:e(()=>[o(i,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20UNI%5B%22%E5%BD%93%E6%97%B6%E4%B8%8A%E5%B8%82%E5%AE%87%E5%AE%99%22%5D%20--%3E%20LONG%5B%22%E5%8F%AF%E8%9E%8D%E8%B5%84%E6%A0%87%E7%9A%84%22%5D%0A%20%20UNI%20--%3E%20SHORT%5B%22%E5%8F%AF%E8%9E%8D%E5%88%B8%E6%A0%87%E7%9A%84%22%5D%0A%20%20SHORT%20--%3E%20RECALL%5B%22%E5%8F%AC%E5%9B%9E%E5%88%99%E5%BC%BA%E5%88%B6%E5%9B%9E%E8%A1%A5%22%5D%0A%20%20LIST%5B%22%E4%BB%8A%E6%97%A5%E5%90%8D%E5%8D%95%E5%9B%9E%E5%A1%AB%22%5D%20--%3E%20BIAS%5B%22%E5%8F%AF%E7%A9%BA%E5%B9%B8%E5%AD%98%E8%80%85%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"可融券名单按日求交之后，还要看是否「只能平仓、不能新开」。后者在 A 股标的调出、美股 hard-to-borrow 极端日都出现。回测把「只能平仓」写成当日空头增量上限为零、已有空头可回补。用空头利息高来反推「当时一定可借」，方向可能反了：利息高常常是供给已紧、增量更借不到。",-1)),a[4]||(a[4]=E("p",null,[E("span",{class:"marginnote"},"常见误区：以为「空头利息高说明现在能借到」。利息高常常是供给已经枯竭的信号——想再借更难、召回也更频繁。判断能否开空，要看当日可借库存与可融名单，而不是昨天的空头利息。")],-1)),a[5]||(a[5]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=E("p",null,"借券供给来自托管长仓、基金出借、库存券。供给紧时，后课费率上升，同时召回概率上升。保证金占用与借券约束叠加：即使维持线未破，召回也能把空头清掉。于是质量空头、盈余负意外空头在最拥挤时最不可实施。回测偏差的方向几乎总是：纸面策略空头赚得太多。",-1)),(n(),l(s,null,{default:e(()=>[o(i,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20SUP%5B%22%E5%80%9F%E5%88%B8%E4%BE%9B%E7%BB%99%3A%20%E6%89%98%E7%AE%A1%E9%95%BF%E4%BB%93%2F%E5%9F%BA%E9%87%91%E5%87%BA%E5%80%9F%2F%E5%BA%93%E5%AD%98%E5%88%B8%22%5D%20--%3E%20DEM%5B%22%E7%A9%BA%E5%A4%B4%E9%9C%80%E6%B1%82%E9%9B%86%E4%B8%AD%22%5D%0A%20%20DEM%20--%3E%20TIGHT%5B%22%E4%BE%9B%E7%BB%99%E5%8F%98%E7%B4%A7%22%5D%0A%20%20TIGHT%20--%3E%20FEE%5B%22%E5%80%9F%E5%88%B8%E8%B4%B9%E7%8E%87%E4%B8%8A%E5%8D%87%22%5D%0A%20%20TIGHT%20--%3E%20RC%5B%22%E5%8F%AC%E5%9B%9E%E6%A6%82%E7%8E%87%E4%B8%8A%E5%8D%87%22%5D%0A%20%20RC%20--%3E%20COVER%5B%22%E9%99%90%E6%9C%9F%E5%9B%9E%E8%A1%A5%E4%B9%B0%E5%85%A5%22%5D%0A%20%20COVER%20--%3E%20UP%5B%22%E9%80%BC%E7%A9%BA%E6%8E%A8%E9%AB%98%E4%BB%B7%E6%A0%BC%22%5D%0A%20%20UP%20--%3E%20LOSS%5B%22%E7%BA%B8%E9%9D%A2%E7%A9%BA%E5%A4%B4%E6%94%B6%E7%9B%8A%E8%A2%AB%E9%AB%98%E4%BC%B0%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p><span class="marginnote">本课不进入限价簿谁先成交。能否借到券是开仓资格；排队与价差是后课 LOB 的事。</span></p><p>形成日负权重先与当时可融券名单求交；不在名单上则空头增量记零。召回按公告限期回补，价格走缺口规则。不要用期末才出现在借券库里的股票回填「一直可空」。A 股融资融券标的调整按生效日更新，今日标的不得覆盖历史。过滤前后空头收益的差，就是纸面异象里不可实施的那一块，应报告而不是加回。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写各市场融资融券管理办法汇编。下一课<a href="/quant/stock-loan-fee">借券费率</a>把资格变成成本。回购是机构之间的抵押融资，机制相近但合约不同，再后一课。后课默认：负权重先过当时可借检查；今日可空名单不得回填。</p><p>后课费率把资格换成成本；没有资格则费率无意义。本课过滤后的空头截面，才是质量与 PEAD 空头真正能交易的那一截。今日可空名单、期末才进入借券库的名字，都不得回填。召回走缺口，不走「按收盘自愿回补」。</p><p>后课默认负权重先过当时可借检查；今日可空名单与期末才进入借券库的名字都不得回填。</p><p>出借人召回给出限期，不是即时市价成交。限期结束时若仍停牌，回补推到复牌第一笔。召回与停牌叠加是空头最差路径，必须允许成交落在限期之后的第一可成交价，而不是在停牌日用标记价假装回补。</p><p>可融券过滤前后的空头收益差要写入回测报告，那是纸面异象里不可实施的部分，不应加回。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>融资借钱、融券借券，可开仓名单不同。</li><li>负权重 ≠ 当时可实施空头。</li><li>召回是另一类强制回补，不必等到维持线。</li><li>空头利息是存量，不是供给的充分统计。</li><li>纸面空头收益偏高，是本课要修的回测偏差。</li><li>出处：D&#39;Avolio (2002)；Geczy, Musto and Reed (2002)。</li></ul>',10))])}const _=B(d,[["render",u]]);export{g as __pageData,_ as default};
